#!/usr/bin/env node
// Downloads the public OGame API files of the universes that merge in the Exodus and writes data.js,
// which index.html reads. Run it by hand whenever you want fresh rankings:
//
//   node exodus/fetch.mjs
//
// Only the official public API (https://s<N>-it.ogame.gameforge.com/api/...) is used: no login, no game
// page, no private data. The highscore files are regenerated by Gameforge about once an hour and
// players/alliances once a day, so there is no point running this more often than that. Requests go
// one at a time with a pause between them. Nothing here runs on a timer (AGENTS.md 1.3, 6).
//
// data.js is a script (window.EXODUS_DATA = ...) rather than a .json file so that index.html also works
// when opened straight from disk: browsers refuse fetch() on file:// pages.

import { writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const COMMUNITY = 'it';

// The Exodus map: each colour group and the destination universes its players can move to.
const GROUPS =
[
    { id:'blue', name:'Blu', color:'#5aa9f0', destinations:['Celestia (IT 284)', 'Zhang (IT 281)'], universes:[264, 265, 267, 269, 270, 274] },
    { id:'orange', name:'Arancio', color:'#efa33c', destinations:['Zhang (IT 281)', 'Astrid (IT 282)'], universes:[195, 254] },
    { id:'green', name:'Verde', color:'#4fc97e', destinations:['Astrid (IT 282)', 'Buzz (IT 283)'], universes:[266, 268, 271, 272, 273, 275, 276] },
];

// highscore.xml?category=1 (players), by type
const CATEGORIES = [ { type:0, key:'total' }, { type:1, key:'economy' }, { type:2, key:'research' }, { type:3, key:'military' } ];

const PAUSE_MS = 400;

const sleep = ms => new Promise(resolve => setTimeout(resolve, ms));

const get = async url =>
{
    for(let attempt = 1; ; attempt++)
    {
        try
        {
            const response = await fetch(url, { headers:{ 'User-Agent':'PrOGect exodus merge (manual run)' } });
            if(!response.ok) throw new Error(`HTTP ${response.status}`);
            return await response.text();
        }
        catch(error)
        {
            if(attempt >= 3) throw new Error(`${url}: ${error.message}`);
            await sleep(2000 * attempt);
        }
        finally
        {
            await sleep(PAUSE_MS);
        }
    }
};

// The API files are flat lists of self-closing tags; their attributes are all that is needed.
const decode = text => text.replace(/&quot;/g, '"').replace(/&apos;/g, "'").replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&amp;/g, '&');
const tags = (xml, name) => Array.from(xml.matchAll(new RegExp(`<${name}\\s([^>]*?)/?>`, 'g')), match =>
{
    const attributes = {};
    for(const [, key, value] of match[1].matchAll(/([\w-]+)="([^"]*)"/g)) attributes[key] = decode(value);
    return attributes;
});
const rootAttribute = (xml, attribute) => (xml.match(new RegExp(`${attribute}="(\\d+)"`)) || [])[1];

const fetchUniverse = async number =>
{
    const base = `https://s${number}-${COMMUNITY}.ogame.gameforge.com/api`;
    const server = await get(`${base}/serverData.xml`);
    const name = decode((server.match(/<name>([^<]*)<\/name>/) || [])[1] || `Universo ${number}`);

    const players = new Map(tags(await get(`${base}/players.xml`), 'player').map(p => [p.id, p]));
    const alliances = new Map(tags(await get(`${base}/alliances.xml`), 'alliance').map(a => [a.id, a]));

    const rows = new Map();
    let updated = 0;

    for(const { type, key } of CATEGORIES)
    {
        const xml = await get(`${base}/highscore.xml?category=1&type=${type}`);
        updated = Math.max(updated, Number(rootAttribute(xml, 'timestamp')) || 0);

        for(const entry of tags(xml, 'player'))
        {
            const player = players.get(entry.id);
            if(player && /a/.test(player.status || '')) continue; // game administrators

            if(!rows.has(entry.id))
            {
                rows.set(entry.id,
                {
                    id:Number(entry.id),
                    name:player?.name || `#${entry.id}`,
                    status:player?.status || '',
                    alliance:alliances.get(player?.alliance)?.tag || '',
                });
            }

            const row = rows.get(entry.id);
            row[key] = [Number(entry.score) || 0, Number(entry.position) || 0];
            if(type === 3) row.ships = Number(entry.ships) || 0;
        }
    }

    // compact rows: [id, name, status, alliance, total, totalPos, economy, economyPos, research, researchPos, military, militaryPos, ships]
    const compact = Array.from(rows.values(), r => [r.id, r.name, r.status, r.alliance,
        ...(r.total || [0, 0]), ...(r.economy || [0, 0]), ...(r.research || [0, 0]), ...(r.military || [0, 0]), r.ships || 0]);

    return { number, name, updated, players:compact };
};

const universes = {};
for(const group of GROUPS)
{
    for(const number of group.universes)
    {
        process.stdout.write(`s${number}-${COMMUNITY} ... `);
        const universe = await fetchUniverse(number);
        universes[number] = universe;
        console.log(`${universe.name}: ${universe.players.length} players`);
    }
}

const data = { generatedAt:Date.now(), community:COMMUNITY, groups:GROUPS, universes };
const out = join(dirname(fileURLToPath(import.meta.url)), 'data.js');
writeFileSync(out, '// Generated by fetch.mjs - do not edit.\nwindow.EXODUS_DATA = ' + JSON.stringify(data) + ';\n');

const total = Object.values(universes).reduce((sum, u) => sum + u.players.length, 0);
console.log(`\n${Object.keys(universes).length} universes, ${total} players -> ${out}`);
